-- Generado automaticamente a partir de 'Autorización Perfile INPOL IA.xlsx' (hoja Sheet1).
-- No editar a mano: regenerar desde el Excel fuente si cambia la matriz de permisos.
-- Catalogo GLOBAL (sin tenant_id): perfiles y funcionalidades son el mismo catalogo para todos los clientes.

create table if not exists perfiles (
  id uuid primary key default gen_random_uuid(),
  clave text not null unique,
  nombre text not null,
  descripcion text,
  orden integer not null default 0,
  activo boolean not null default true,
  creado_en timestamptz not null default now()
);

create table if not exists funcionalidades (
  id uuid primary key default gen_random_uuid(),
  clave text not null unique,
  modulo text not null,
  ruta text[] not null,
  etiqueta text not null,
  fase integer,
  orden integer not null default 0,
  creado_en timestamptz not null default now()
);

create table if not exists perfil_funcionalidades (
  perfil_clave text not null references perfiles(clave) on delete cascade,
  funcionalidad_clave text not null references funcionalidades(clave) on delete cascade,
  primary key (perfil_clave, funcionalidad_clave)
);

-- Perfiles
on conflict (clave) do nothing;

-- Funcionalidades
on conflict (clave) do nothing;

-- Relacion perfil <-> funcionalidad
on conflict (perfil_clave, funcionalidad_clave) do nothing;
